ValidationRule.errorConditionFormula:
AND(
    /* Bypass validation for authorized rollback users */
    NOT($Permission.Zeta_Rollback_Lottery),

    TEXT(PRIORVALUE(Status)) = "Offer Rescinded due to Seat Optimization",

    /* Only validate when Status actually changes */
    TEXT(Status) <> TEXT(PRIORVALUE(Status)),

    /* Allow Withdrawn/Declined OR Seat Offered */
    NOT(
        OR(
            ISPICKVAL(Status, "Withdrawn/Declined"),
            ISPICKVAL(Status, "Seat Offered"), 
            ISPICKVAL(Status, "Seat Accepted") 
        )
    )
)
